"""Validate the PDF generated by profile-2-qa.cjs; requires PyMuPDF."""
import sys
import fitz
pdf = fitz.open(sys.argv[1] if len(sys.argv)>1 else '/tmp/profile-qa-output/profile.pdf')
text='\n'.join(page.get_text() for page in pdf)
for marker in ['Teszt Tanuló', '12. C', 'II. József', 'PDF_END_MARKER', 'Képforrások']:
    assert marker in text, marker
for page in pdf:
    assert abs(page.rect.width-595.28)<2 and abs(page.rect.height-841.89)<2
    assert page.get_text().strip(), 'Empty PDF page'
print(f'PASS: {len(pdf)} A4 pages; student, diacritics, image attribution and end marker retained')
